  ccxt::any parseFundingRate(ccxt::any contract,
                             ccxt::any market = ccxt::any{}) override {
    //
    // ticker/24hr contract rows
    //     {
    //         "symbol": "ETH-PERP-USDT",
    //         "lastPrice": "1896.17",
    //         "openPrice": "1887.07",
    //         "highPrice": "1924",
    //         "lowPrice": "1872.44",
    //         "amount": "1937140691",
    //         "volume": "366459222.269293",
    //         "openTime": 1786518000,
    //         "closeTime": 1786607054,
    //         "priceChange": "9.1",
    //         "priceChangePercent": "0.005",
    //         "prevClosePrice": "1897.71",
    //         "bidPrice": "1896",
    //         "bidQty": "105",
    //         "askPrice": "1896.01",
    //         "askQty": "11354",
    //         "openInterest": "19344237",
    //         "fundingRate": "0.00006016",
    //         "nextFundingTime": 1786608000000,
    //         "fundingIntervalMinutes": 480
    //     }
    //
    ccxt::any marketId = this->safeString(contract, std::string("symbol"));
    market = this->safeMarket(marketId, market);
    ccxt::any timestamp =
        this->safeTimestamp(contract, std::string("closeTime"));
    // dated futures carry a zero nextFundingTime as funding only applies to
    // perpetuals, observed live, the zero means no next funding and is omitted
    ccxt::any nextFundingTimestamp =
        this->safeIntegerOmitZero(contract, std::string("nextFundingTime"));
    ccxt::any fundingIntervalMinutes =
        this->safeInteger(contract, std::string("fundingIntervalMinutes"));
    ccxt::any interval = ccxt::any{};
    // a wire value of zero minutes reaches this, and zero hours is not an
    // interval: a caller annualising a rate divides by it. anything under an
    // hour rounds to the same string, and the vocabulary has no minutes
    if (isTrue(isTrue((!isEqual(fundingIntervalMinutes, ccxt::any{}))) &&
               isTrue((isGreaterThanOrEqual(fundingIntervalMinutes, 60))))) {
      ccxt::any hours = this->parseToInt(divide(fundingIntervalMinutes, 60));
      interval = add(toString(hours), std::string("h"));
    }
    return ccxt::dict{
        {std::string("info"), contract},
        {std::string("symbol"), ::getValue(market, std::string("symbol"))},
        {std::string("markPrice"), ccxt::any{}},
        {std::string("indexPrice"), ccxt::any{}},
        {std::string("interestRate"), ccxt::any{}},
        {std::string("estimatedSettlePrice"), ccxt::any{}},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("fundingRate"),
         this->safeNumber(contract, std::string("fundingRate"))},
        {std::string("fundingTimestamp"), ccxt::any{}},
        {std::string("fundingDatetime"), ccxt::any{}},
        {std::string("nextFundingRate"), ccxt::any{}},
        {std::string("nextFundingTimestamp"), nextFundingTimestamp},
        {std::string("nextFundingDatetime"),
         this->iso8601(nextFundingTimestamp)},
        {std::string("previousFundingRate"), ccxt::any{}},
        {std::string("previousFundingTimestamp"), ccxt::any{}},
        {std::string("previousFundingDatetime"), ccxt::any{}},
        {std::string("interval"), interval},
    };
  }

  /**
   * @method
   * @name btse#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see https://docs.btse.com/markets/rest/get-trades/
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch,
   * applied client-side to the most recent trades window
   * @param {int} [limit] the maximum amount of trades to fetch (max 500)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest entry to fetch,
   * applied client-side to the most recent trades window
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<ccxt::any>
  fetchTrades(ccxt::any symbol, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"),
                              mathMin(limit, 500)); // the endpoint supports a
                                                    // maximum of 500 trades
                 }
                 // the unified trades endpoint has no server-side time
                 // filtering, since and until are applied client-side below
                 ccxt::any until = ccxt::any{};
                 ccxt::any untilparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchTrades"), std::string("until"));
                 until = ::getValue(untilparamsVariable, 0);
                 params = ::getValue(untilparamsVariable, 1);
                 ccxt::any response =
                     awaitValue(this->publicGetPublicApiMarketV1Trades(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "data": [
                 //             {
                 //                 "id": 91151062,
                 //                 "timestamp": 1786605669577,
                 //                 "price": "1896.3291755587",
                 //                 "size": "0.06",
                 //                 "quoteSize": "113.7797505335",
                 //                 "side": "BUY"
                 //             }
                 //         ],
                 //         "code": 1,
                 //         "msg": "Success",
                 //         "success": true,
                 //         "time": 1786605671650
                 //     }
                 //
                 ccxt::any data = this->safeList(response, std::string("data"),
                                                 ccxt::list{});
                 ccxt::any trades =
                     this->parseTrades(data, market, since, limit);
                 if (isTrue(isEqual(until, ccxt::any{}))) {
                   return trades;
                 }
                 ccxt::any result = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(trades));
                      postFixIncrement(i)) {
                   ccxt::any trade = ::getValue(trades, i);
                   ccxt::any timestamp =
                       this->safeInteger(trade, std::string("timestamp"));
                   if (isTrue(isTrue((isEqual(timestamp, ccxt::any{}))) ||
                              isTrue((isLessThanOrEqual(timestamp, until))))) {
                     arrayPush(result, trade);
                   }
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name btse#fetchMyTrades
   * @description fetch all trades made by the user
   * @see https://docs.btse.com/spot/rest/get-trade-history/
   * @see https://docs.btse.com/futures/rest/get-trade-history/
   * @param {string} [symbol] unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms for the ending date filter,
   * default is undefined
   * @param {string} [params.type] 'spot' or 'swap' or 'future', default is
   * 'spot'
   * @returns {object[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/#/?id=trade-structure}
   */
  std::shared_future<ccxt::any>
  fetchMyTrades(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any paginate =
                     this->safeBool(params, std::string("paginate"), false);
                 if (isTrue(isEqual(paginate, true))) {
                   params = this->omit(params, std::string("paginate"));
                   return awaitValue(this->fetchPaginatedCallDynamic(
                       std::string("fetchMyTrades"), symbol, since, limit,
                       params));
                 }
                 ccxt::any market = ccxt::any{};
                 ccxt::any request = ccxt::dict{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("count"), limit);
                 }
                 ccxt::any requestparamsVariable = this->handleUntilOption(
                     std::string("endTime"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 ccxt::any marketType = std::string("spot");
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchMyTrades"), market, params,
                         marketType);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   if (isTrue(isEqual(symbol, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(
                         add(this->id,
                             std::string(" fetchMyTrades() requires a symbol "
                                         "argument for spot markets"))));
                   }
                   //
                   //     {
                   //         "data": [
                   //             {
                   //                 "serialId": 375599088,
                   //                 "tradeId":
                   //                 "de1a79b8-f408-4e05-b8b7-7ed3c4e86542",
                   //                 "orderId":
                   //                 "6c72d906-cb8f-469c-8ab0-b97bc8dff9c2",
                   //                 "clOrderId": null,
                   //                 "symbol": "BTC-USD",
                   //                 "base": "BTC",
                   //                 "quote": "USD",
                   //                 "orderSide": "BUY",
                   //                 "orderType": 77,
                   //                 "triggerType": 0,
                   //                 "triggerPrice": 0,
                   //                 "price": 64235.97008,
                   //                 "size": 1.9,
                   //                 "filledSize": 0.00002,
                   //                 "feeCurrency": "BTC",
                   //                 "feeAmount": 1e-8,
                   //                 "timestamp": 1784890959551
                   //             }
                   //         ],
                   //         "code": 1,
                   //         "msg": "Success",
                   //         "success": true,
                   //         "time": 1786610160164
                   //     }
                   //
                   response =
                       awaitValue(this->privateGetSpotApiV4TradeTradeHistory(
                           this->extend(request, params)));
                 } else {
                   // the futures endpoint does not support a count parameter,
                   // the limit is applied client-side
                   request = this->omit(request, std::string("count"));
                   if (isTrue(!isEqual(market, ccxt::any{}))) {
                     ::setValue(request, std::string("symbol"),
                                this->futuresRequestId(market));
                   }
                   //
                   //     {
                   //         "data": [
                   //             {
                   //                 "tradeId":
                   //                 "1ad38104-6248-4a45-bc56-5fa9bf7f3868",
                   //                 "orderId":
                   //                 "8ad94105-8cce-4e01-86b8-2d0fb403db66",
                   //                 "clOrderId": "",
                   //                 "positionId": "BTC-PERP-USDT",
                   //                 "orderSide": "BUY",
                   //                 "type": 77,
                   //                 "orderDetailType": null,
                   //                 "price": 0,
                   //                 "size": 1,
                   //                 "avgFilledPrice": 60010,
                   //                 "filledSize": 1,
                   //                 "triggerPrice": 0,
                   //                 "contractSize": 0.00001,
                   //                 "base": "BTC",
                   //                 "quote": "USDT",
                   //                 "symbol": "BTC-PERP",
                   //                 "wallet": "BTC-PERP Isolated Wallet",
                   //                 "feeCurrency": "USDT",
                   //                 "feeAmount": 0.00012002,
                   //                 "realizedPnl": 0,
                   //                 "total": -0.00012002,
                   //                 "serialId": 375598162,
                   //                 "timestamp": 1784882344446
                   //             }
                   //         ],
                   //         "code": 1,
                   //         "msg": "Success",
                   //         "success": true,
                   //         "time": 1786610160164
                   //     }
                   //
                   response =
                       awaitValue(this->privateGetFuturesApiV3TradeTradeHistory(
                           this->extend(request, params)));
                 }
                 ccxt::any rows = this->safeList(response, std::string("data"));
                 if (isTrue(isEqual(rows, ccxt::any{}))) {
                   rows = response;
                 }
                 return this->parseTrades(rows, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name btse#fetchOrderTrades
   * @description fetch all the trades made from a single order
   * @see https://btsecom.github.io/docs/spotV3_3/en/#query-user-trades-fills
   * @see https://btsecom.github.io/docs/futuresV2_3/en/#query-trades-fills-2
   * @param {string} id order id
   * @param {string} [symbol] unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.clientOrderId] client order id, could be used
   * instead of the order id
   * @param {string} [params.type] 'spot' or 'swap' or 'future', default is
   * 'spot'
   * @returns {object[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderTrades(ccxt::any id, ccxt::any symbol = ccxt::any{},
                   ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
                   ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any clientOrderId =
                     this->safeString(params, std::string("clientOrderId"));
                 if (isTrue(isEqual(clientOrderId, ccxt::any{}))) {
                   if (isTrue(isEqual(id, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(
                         add(this->id,
                             std::string(
                                 " fetchOrderTrades() requires an id argument "
                                 "or a clientOrderId parameter"))));
                   } else {
                     params =
                         this->extend(params, ccxt::dict{
                                                  {std::string("orderID"), id},
                                              });
                   }
                 } else {
                   params = this->extend(
                       params, ccxt::dict{
                                   {std::string("clOrderID"), clientOrderId},
                               });
                 }
                 return awaitValue(
                     this->fetchMyTrades(symbol, since, limit, params));
               })
        .share();
  }

  ccxt::any parseTrade(ccxt::any trade,
                       ccxt::any market = ccxt::any{}) override {
    //
    // fetchTrades
    //     {
    //         "id": 91151062,
    //         "timestamp": 1786605669577,
    //         "price": "1896.3291755587",
    //         "size": "0.06",
    //         "quoteSize": "113.7797505335",
    //         "side": "BUY"
    //     }
    //
    // fetchMyTrades spot
    //     {
    //         "tradeId": "4b4bd301-6f20-4e39-a682-ce4f9b8400a0",
    //         "orderId": "2fa9678b-9945-47ce-9ffe-256dc7b4dd8c",
    //         "clOrderID": "test spot market buy",
    //         "username": "romancuhari",
    //         "side": "BUY",
    //         "orderType": 77,
    //         "triggerType": 0,
    //         "price": 1952.05859608,
    //         "size": 0.19520586,
    //         "filledPrice": 1952.05859608,
    //         "filledSize": 0.0001,
    //         "triggerPrice": 0,
    //         "base": "ETH",
    //         "quote": "USDT",
    //         "symbol": "ETH-USDT",
    //         "feeCurrency": "ETH",
    //         "feeAmount": 0.0000002,
    //         "wallet": "SPOT@",
    //         "realizedPnl": 0,
    //         "total": 0,
    //         "serialId": 49071052,
    //         "timestamp": 1770814978685,
    //         "avgFilledPrice": 1952.05859608
    //     }
    //
    // fetchMyTrades swap
    //     {
    //         "tradeId": "b708489a-19d1-4be2-a6c2-f499f76aa176",
    //         "orderId": "5c6a26db-8cfb-45c7-b25d-56927bc36795",
    //         "username": "romancuhari",
    //         "side": "BUY",
    //         "orderType": 77,
    //         "triggerType": null,
    //         "price": 0,
    //         "size": 1,
    //         "filledPrice": 1956.59,
    //         "filledSize": 1,
    //         "triggerPrice": 0,
    //         "base": "ETH",
    //         "quote": "USDT",
    //         "symbol": "ETH-PERP",
    //         "feeCurrency": "USDT",
    //         "feeAmount": 0.00010761,
    //         "wallet": "CROSS@",
    //         "realizedPnl": 0,
    //         "total": -0.00010761,
    //         "serialId": 50953296,
    //         "timestamp": 1770821231984,
    //         "orderDetailType": null,
    //         "contractSize": 0.0001,
    //         "clOrderID": "",
    //         "positionId": "ETH-PERP-USDT",
    //         "avgFilledPrice": 1956.59
    //     }
    //
    // the unified futures rows echo the short symbol form but carry the full
    // market id in positionId, which resolves against the markets snapshot
    ccxt::any marketId = this->safeString2(trade, std::string("positionId"),
                                           std::string("symbol"));
    market = this->safeMarket(marketId, market);
    ccxt::any timestamp = this->safeInteger(trade, std::string("timestamp"));
    ccxt::any fee = ccxt::any{};
    ccxt::any feeCost = this->safeNumber(trade, std::string("feeAmount"));
    if (isTrue(!isEqual(feeCost, ccxt::any{}))) {
      fee = ccxt::dict{
          {std::string("cost"), feeCost},
          {std::string("currency"), this->safeCurrencyCode(this->safeString(
                                        trade, std::string("feeCurrency")))},
      };
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("info"), trade},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("id"),
             this->safeStringN(trade, ccxt::list{std::string("tradeId"),
                                                 std::string("serialId"),
                                                 std::string("id")})},
            {std::string("order"),
             this->safeString(trade, std::string("orderId"))},
            {std::string("type"),
             this->parseOrderType(this->safeString2(
                 trade, std::string("orderType"), std::string("type")))},
            {std::string("side"),
             this->safeStringLower2(trade, std::string("side"),
                                    std::string("orderSide"))},
            {std::string("takerOrMaker"), ccxt::any{}},
            {std::string("price"),
             this->safeStringN(trade, ccxt::list{std::string("filledPrice"),
                                                 std::string("avgFilledPrice"),
                                                 std::string("price")})},
            {std::string("amount"),
             this->safeString2(trade, std::string("filledSize"),
                               std::string("size"))},
            {std::string("cost"), ccxt::any{}},
            {std::string("fee"), fee},
        },
        market);
  }

  /**
   * @method
   * @name btse#createOrder
   * @description create a trade order
   * @see https://btsecom.github.io/docs/spotV3_3/en/#create-new-order
   * @see https://btsecom.github.io/docs/futuresV2_3/en/#create-new-order
   * @see https://btsecom.github.io/docs/futuresV2_3/en/#create-new-algo-order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fullfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.clientOrderId] a unique id for the order
   * @param {bool} [params.postOnly] if true, the order will only be posted to
   * the order book and not executed immediately (default is false)
   * @param {string} [params.timeInForce] 'GTC', 'IOC', 'FOK', 'PO', 'HALFMIN',
   * 'FIVEMIN', 'HOUR', 'TWELVEHOUR', 'DAY', 'WEEK' or 'MONTH'
   * @param {float} [params.triggerPrice] the price that a trigger order is
   * triggered at (same as takeProfitPrice)
   * @param {float} [params.stopLossPrice] the price that a stop loss order is
   * triggered at
   * @param {float} [params.takeProfitPrice] the price that a take profit order
   * is triggered at
   * @param {string} [params.triggerPriceType] 'INDEX_PRICE' or 'LAST_PRICE',
   * default is 'LAST_PRICE'
   * @param {float} [params.trailingAmount] the quote amount to trail away from
   * the current market price
   * @param {float} [params.deviation] *PEG orders only* How much should the
   * order price deviate from index price. Value is in percentage and can range
   * from -10 to 10
   * @param {float} [params.stealth] *PEG orders only*  How many percent of the
   * order is to be displayed on the orderbook
   * @param {float} [params.stopPrice] *NB - It is NOT stopLossPrice or
   * triggerPrice!!! OCO orders only* Mandatory when creating an OCO order.
   * Indicates the stop price
   * @param {bool} [params.hedged] *contract markets only* true for hedged mode,
   * false for one way mode, default is false
   * @param {string} [params.marginMode] *contract markets only* 'cross' or
   * 'isolated' (default is 'cross') - the exchange does not have cross/isolated
   * margin modes but instead has 'ONE_WAY', 'HEDGE' and 'ISOLATED' position
   * modes, so this param will be converted to the appropriate position mode
   * @param {string} [params.positionMode] *contract markets only* 'ONE_WAY
   * (default) or 'HEDGE or 'ISOLATED' (if not provided, it will be derived from
   * marginMode and hedged params)
   * @param {object} [params.takeProfit] *contract markets only* *takeProfit
   * object in params* containing the triggerPrice at which the attached take
   * profit order will be triggered (perpetual swap markets only)
   * @param {float} [params.takeProfit.triggerPrice] *contract markets only*
   * take profit trigger price
   * @param {string} [params.takeProfit.priceType] *contract markets only*
   * 'markPrice' or 'lastPrice', default is 'markPrice'
   * @param {object} [params.stopLoss] *contract markets only* *stopLoss object
   * in params* containing the triggerPrice at which the attached stop loss
   * order will be triggered (perpetual swap markets only)
   * @param {float} [params.stopLoss.triggerPrice] *contract markets only* stop
   * loss trigger price
   * @param {string} [params.stopLoss.priceType] *contract markets only*
   * 'markPrice' or 'lastPrice', default is 'markPrice'
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
              ccxt::any amount, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any market = this->market(symbol);
                 if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                    true))) {
                   return awaitValue(this->createSpotOrder(
                       symbol, type, side, amount, price, params));
                 } else {
                   return awaitValue(this->createContractOrder(
                       symbol, type, side, amount, price, params));
                 }
                 return ccxt::any{};
               })
        .share();
  }

  /**
   * @method
   * @name btse#createSpotOrder
   * @description create a trade order on spot market
   * @see https://docs.btse.com/spot/rest/place-order
   * @see https://docs.btse.com/spot/rest/place-algo-order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market', 'limit', 'OCO', 'PEG', 'TWAP' or 'TRAILING'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of you want to trade in units of the base
   * currency
   * @param {float} [price] the price that the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.clientOrderId] a unique id for the order
   * @param {bool} [params.postOnly] if true, the order will only be posted to
   * the order book and not executed immediately, default is false
   * @param {string} [params.timeInForce] 'GTC', 'IOC' or 'FOK'
   * @param {float} [params.cost] *market buy and trailing buy orders only* the
   * quote quantity that can be used as an alternative for the amount
   * @param {float} [params.triggerPrice] the price that a trigger order is
   * triggered at, same as takeProfitPrice
   * @param {float} [params.stopLossPrice] the price that a stop loss order is
   * triggered at
   * @param {float} [params.takeProfitPrice] the price that a take profit order
   * is triggered at
   * @param {string} [params.triggerPriceType] 'last', 'mark' or 'index',
   * default is 'last'
   * @param {float} [params.trailingAmount] the quote amount to trail away from
   * the current market price
   * @param {float} [params.trailingPercent] the percent to trail away from the
   * current market price
   * @param {float} [params.deviation] *PEG orders only* how much should the
   * order price deviate from the pegged price, in percent from -10 to 10
   * @param {float} [params.stealth] *PEG orders only* how many percent of the
   * order is to be displayed on the orderbook, from 1 to 100
   * @param {float} [params.stopPrice] *NB - It is NOT stopLossPrice or
   * triggerPrice!!! OCO orders only* the limit price of the stop loss leg
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<ccxt::any>
  createSpotOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
                  ccxt::any amount, ccxt::any price = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any market = this->market(symbol);
                 type = toUpperCase(type);
                 ccxt::any upperSide = toUpperCase(side);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("orderSide"), upperSide},
                 };
                 ccxt::any clientOrderId =
                     this->safeString(params, std::string("clientOrderId"));
                 if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
                   ::setValue(request, std::string("clOrderId"), clientOrderId);
                   params = this->omit(params, std::string("clientOrderId"));
                 }
                 ccxt::any isMarketOrder =
                     (isEqual(type, std::string("MARKET")));
                 ccxt::any isLimitOrder = (isEqual(type, std::string("LIMIT")));
                 ccxt::any postOnly = false;
                 // exchange-specific postOnly is the same as the unified one
                 ccxt::any postOnlyparamsVariable =
                     this->handlePostOnly(isMarketOrder, postOnly, params);
                 postOnly = ::getValue(postOnlyparamsVariable, 0);
                 params = ::getValue(postOnlyparamsVariable,
                                     1); // this will remove PO from
                                         // params.timeInForce if present
                 if (isTrue(postOnly)) {
                   ::setValue(request, std::string("postOnly"), true);
                 }
                 ccxt::any timeInForce = this->handleTimeInForce(params);
                 if (isTrue(!isEqual(timeInForce, ccxt::any{}))) {
                   ::setValue(request, std::string("timeInForce"), timeInForce);
                 }
                 ccxt::any triggerPrice =
                     this->safeString(params, std::string("triggerPrice"));
                 ccxt::any takeProfitPrice =
                     this->safeString(params, std::string("takeProfitPrice"));
                 ccxt::any stopLossPrice =
                     this->safeString(params, std::string("stopLossPrice"));
                 ccxt::any isTriggerOrder =
                     isTrue((!isEqual(triggerPrice, ccxt::any{}))) ||
                     isTrue((!isEqual(takeProfitPrice, ccxt::any{})));
                 ccxt::any isStopLossOrder =
                     (!isEqual(stopLossPrice, ccxt::any{}));
                 ccxt::any isConditionalOrder =
                     isTrue(
                         (isTrue(isTriggerOrder) || isTrue(isStopLossOrder))) &&
                     isTrue((isTrue(isMarketOrder) || isTrue(isLimitOrder)));
                 ccxt::any isAlgoOrder =
                     isTrue(isConditionalOrder) ||
                     isTrue((!isTrue(isMarketOrder) && !isTrue(isLimitOrder)));
                 if (isTrue(
                         isTrue(isTrue(isLimitOrder) ||
                                isTrue((isEqual(type, std::string("PEG"))))) ||
                         isTrue((isEqual(type, std::string("OCO")))))) {
                   if (isTrue(isEqual(price, ccxt::any{}))) {
                     throw InvalidOrder(toString(
                         add(add(add(this->id,
                                     std::string(" createOrder() requires a "
                                                 "price argument for ")),
                                 type),
                             std::string(" orders"))));
                   }
                 }
                 // market and trailing buys are denominated in the quote
                 // currency while every other combination is denominated in the
                 // base currency, the sizing rules are strict on both sides,
                 // verified live
                 ccxt::any needsQuoteSize =
                     isTrue(
                         (isTrue(isMarketOrder) ||
                          isTrue((isEqual(type, std::string("TRAILING")))))) &&
                     isTrue((isEqual(upperSide, std::string("BUY"))));
                 if (isTrue(needsQuoteSize)) {
                   ccxt::any quoteAmount = ccxt::any{};
                   ccxt::any createMarketBuyOrderRequiresPrice = true;
                   ccxt::any createMarketBuyOrderRequiresPriceparamsVariable =
                       this->handleOptionAndParams(
                           params, std::string("createOrder"),
                           std::string("createMarketBuyOrderRequiresPrice"),
                           true);
                   createMarketBuyOrderRequiresPrice = ::getValue(
                       createMarketBuyOrderRequiresPriceparamsVariable, 0);
                   params = ::getValue(
                       createMarketBuyOrderRequiresPriceparamsVariable, 1);
                   ccxt::any cost =
                       this->safeString(params, std::string("cost"));
                   params = this->omit(params, std::string("cost"));
                   if (isTrue(!isEqual(cost, ccxt::any{}))) {
                     quoteAmount = this->costToPrecision(symbol, cost);
                   } else if (isTrue(createMarketBuyOrderRequiresPrice)) {
                     if (isTrue(isEqual(price, ccxt::any{}))) {
                       throw InvalidOrder(toString(
                           add(this->id,
                               std::string(
                                   " createOrder() requires the price argument "
                                   "for market buy orders to calculate the "
                                   "total cost to spend, alternatively set the "
                                   "createMarketBuyOrderRequiresPrice option "
                                   "or param to false and pass the cost to "
                                   "spend in the amount argument"))));
                     } else {
                       ccxt::any amountString = this->numberToString(amount);
                       ccxt::any priceString = this->numberToString(price);
                       quoteAmount = this->costToPrecision(
                           symbol,
                           ccxt::Precise::stringMul(amountString, priceString));
                     }
                   } else {
                     quoteAmount = this->costToPrecision(
                         symbol, this->numberToString(amount));
                   }
                   ::setValue(request, std::string("quoteOrderSize"),
                              quoteAmount);
                 } else {
                   ::setValue(request, std::string("orderSize"),
                              this->amountToPrecision(symbol, amount));
                 }
                 ccxt::any response = ccxt::any{};
                 if (!isTrue(isAlgoOrder)) {
                   ::setValue(request, std::string("orderType"), type);
                   if (isTrue(isLimitOrder)) {
                     ::setValue(request, std::string("orderPrice"),
                                this->priceToPrecision(symbol, price));
                   }
                   //
                   //     [
                   //         {
                   //             "orderId":
                   //             "4eca2eb4-e6ad-4355-ae12-5ce757b105b3",
                   //             "clOrderId": "",
                   //             "status": 2,
                   //             "market": "BTC-USD",
                   //             "type": 76,
                   //             "orderSide": "BUY",
                   //             "orderPrice": 61024.1,
                   //             "postOnly": false,
                   //             "timestamp": 1784891308063,
                   //             "orderDetailType": null,
                   //             "message": null,
                   //             "userQuoteCurrency": "USD",
                   //             "orderCurrency": "base",
                   //             "originalOrderBaseSize": 0.00001,
                   //             "originalOrderQuoteSize": null,
                   //             "currentOrderBaseSize": 0.00001,
                   //             "currentOrderQuoteSize": null,
                   //             "remainingOrderBaseSize": 0.00001,
                   //             "remainingOrderQuoteSize": null,
                   //             "filledBaseSize": 0,
                   //             "totalFilledBaseSize": 0,
                   //             "avgFilledPrice": 0,
                   //             "time_in_force": "GTC"
                   //         }
                   //     ]
                   //
                   response = awaitValue(this->privatePostSpotApiV4TradeOrders(
                       this->extend(request, params)));
                 } else {
                   if (isTrue(isConditionalOrder)) {
                     ::setValue(request, std::string("orderType"),
                                std::string("CONDITIONAL"));
                     ccxt::any triggerOrderType = ccxt::any{};
                     ccxt::any triggerPriceToSend = ccxt::any{};
                     if (isTrue(isStopLossOrder)) {
                       triggerOrderType = std::string("STOP_LOSS");
                       triggerPriceToSend = stopLossPrice;
                     } else {
                       triggerOrderType = std::string("TAKE_PROFIT");
                       triggerPriceToSend = triggerPrice;
                       if (isTrue(isEqual(triggerPriceToSend, ccxt::any{}))) {
                         triggerPriceToSend = takeProfitPrice;
                       }
                     }
                     if (isTrue(isLimitOrder)) {
                       triggerOrderType =
                           add(triggerOrderType, std::string("_LIMIT"));
                       ::setValue(request, std::string("orderPrice"),
                                  this->priceToPrecision(symbol, price));
                     }
                     ::setValue(request, std::string("triggerOrderType"),
                                triggerOrderType);
                     ::setValue(
                         request, std::string("triggerPrice"),
                         this->priceToPrecision(symbol, triggerPriceToSend));
                     ccxt::any triggerPriceType = this->safeString(
                         params, std::string("triggerPriceType"),
                         std::string("last"));
                     ::setValue(request, std::string("triggerPriceType"),
                                this->encodeTriggerPriceType(triggerPriceType));
                     params = this->omit(
                         params, ccxt::list{std::string("triggerPrice"),
                                            std::string("takeProfitPrice"),
                                            std::string("stopLossPrice"),
                                            std::string("triggerPriceType")});
                   } else {
                     ::setValue(request, std::string("orderType"), type);
                     if (isTrue(isEqual(type, std::string("OCO")))) {
                       // the price argument is the limit price of the take
                       // profit leg, the stopPrice param is the limit price of
                       // the stop loss leg and the triggerPrice param is where
                       // the stop loss leg fires
                       ::setValue(request, std::string("takeProfitOrderPrice"),
                                  this->priceToPrecision(symbol, price));
                       ccxt::any stopPrice =
                           this->safeString(params, std::string("stopPrice"));
                       if (isTrue(!isEqual(stopPrice, ccxt::any{}))) {
                         ::setValue(request, std::string("stopLossOrderPrice"),
                                    this->priceToPrecision(symbol, stopPrice));
                       }
                       if (isTrue(!isEqual(triggerPrice, ccxt::any{}))) {
                         ::setValue(
                             request, std::string("stopLossTriggerPrice"),
                             this->priceToPrecision(symbol, triggerPrice));
                       }
                       ccxt::any triggerPriceType = this->safeString(
                           params, std::string("triggerPriceType"),
                           std::string("last"));
                       ::setValue(
                           request, std::string("stopLossTriggerPriceType"),
                           this->encodeTriggerPriceType(triggerPriceType));
                       params = this->omit(
                           params, ccxt::list{std::string("stopPrice"),
                                              std::string("triggerPrice"),
                                              std::string("triggerPriceType")});
                     } else if (isTrue(isEqual(type, std::string("PEG")))) {
                       // the required stealth and optional deviation params
                       // pass through
                       ::setValue(request, std::string("orderPrice"),
                                  this->priceToPrecision(symbol, price));
                     } else if (isTrue(
                                    isEqual(type, std::string("TRAILING")))) {
                       ccxt::any trailingAmount = this->safeString(
                           params, std::string("trailingAmount"));
                       ccxt::any trailingPercent = this->safeString(
                           params, std::string("trailingPercent"));
                       if (isTrue(!isEqual(trailingAmount, ccxt::any{}))) {
                         ::setValue(
                             request, std::string("trailValue"),
                             this->priceToPrecision(symbol, trailingAmount));
                         ::setValue(request, std::string("trailValueType"),
                                    std::string("DISTANCE"));
                       } else if (isTrue(
                                      !isEqual(trailingPercent, ccxt::any{}))) {
                         ::setValue(request, std::string("trailValue"),
                                    trailingPercent);
                         ::setValue(request, std::string("trailValueType"),
                                    std::string("PERCENTAGE"));
                       }
                       ccxt::any triggerPriceType = this->safeString(
                           params, std::string("triggerPriceType"),
                           std::string("last"));
                       ::setValue(
                           request, std::string("triggerPriceType"),
                           this->encodeTriggerPriceType(triggerPriceType));
                       params = this->omit(
                           params, ccxt::list{std::string("trailingAmount"),
                                              std::string("trailingPercent"),
                                              std::string("triggerPriceType")});
                     }
                   }
                   response =
                       awaitValue(this->privatePostSpotApiV4TradeOrdersAlgo(
                           this->extend(request, params)));
                 }
                 ccxt::any order = this->safeDict(response, 0, ccxt::dict{});
                 return this->parseOrder(order, market);
               })
        .share();
  }

  /**
   * @method
   * @name btse#createContractOrder
   * @description create a trade order on contract market
   * @see https://docs.btse.com/futures/rest/place-order
   * @see https://docs.btse.com/futures/rest/place-algo-order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market', 'limit', 'OCO', 'PEG', 'TWAP' or 'TRAILING'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of you want to trade in units of the base
   * currency
   * @param {float} [price] the price that the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.clientOrderId] a unique id for the order
   * @param {bool} [params.postOnly] if true, the order will only be posted to
   * the order book and not executed immediately, default is false
   * @param {bool} [params.reduceOnly] if true, the order will only reduce a
   * current position, not increase it, default is false
   * @param {string} [params.timeInForce] 'GTC', 'IOC', 'FOK', 'PO', 'HALFSEC',
   * 'HALFMIN', 'FIVEMIN', 'HOUR', 'TWELVEHOUR', 'DAY', 'WEEK' or 'MONTH'
   * @param {bool} [params.hedged] true for hedged mode, false for one way mode,
   * default is false
   * @param {string} [params.marginMode] 'cross' or 'isolated', default is
   * 'cross' - the exchange does not have cross/isolated margin modes but
   * instead has 'ONE_WAY', 'HEDGE' and 'ISOLATED' position modes, so this param
   * will be converted to the appropriate position mode
   * @param {string} [params.positionMode] 'ONE_WAY', 'HEDGE' or 'ISOLATED' - if
   * not provided, it will be derived from the marginMode and hedged params
   * @param {float} [params.triggerPrice] the price that a trigger order is
   * triggered at, same as takeProfitPrice
   * @param {float} [params.stopLossPrice] the price that a stop loss order is
   * triggered at
   * @param {float} [params.takeProfitPrice] the price that a take profit order
   * is triggered at
   * @param {string} [params.triggerPriceType] 'last', 'mark' or 'index',
   * default is 'mark'
   * @param {float} [params.trailingAmount] the quote amount to trail away from
   * the current market price
   * @param {float} [params.trailingPercent] the percent to trail away from the
   * current market price
   * @param {object} [params.takeProfit] *takeProfit object in params*
   * containing the triggerPrice at which the attached take profit order will be
   * triggered
   * @param {float} [params.takeProfit.triggerPrice] take profit trigger price
   * @param {string} [params.takeProfit.priceType] 'last', 'mark' or 'index',
   * default is 'mark'
   * @param {object} [params.stopLoss] *stopLoss object in params* containing
   * the triggerPrice at which the attached stop loss order will be triggered
   * @param {float} [params.stopLoss.triggerPrice] stop loss trigger price
   * @param {string} [params.stopLoss.priceType] 'last', 'mark' or 'index',
   * default is 'mark'
   * @param {float} [params.deviation] *PEG orders only* the offset applied to
   * the pegged reference price
   * @param {float} [params.stealth] *PEG orders only* the portion of the order
   * size displayed on the book
   * @param {float} [params.stopPrice] *NB - It is NOT the stopLossPrice!!! OCO
   * orders only* the limit price of the stop loss leg
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<ccxt::any>
  createContractOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
                      ccxt::any amount, ccxt::any price = ccxt::any{},
                      ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any market = this->market(symbol);
                 type = toUpperCase(type);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"), this->futuresRequestId(market)},
                     {std::string("orderSide"), toUpperCase(side)},
                     {std::string("orderSize"),
                      this->amountToPrecision(symbol, amount)},
                 };
                 ccxt::any clientOrderId =
                     this->safeString(params, std::string("clientOrderId"));
                 if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
                   ::setValue(request, std::string("clOrderId"), clientOrderId);
                   params = this->omit(params, std::string("clientOrderId"));
                 }
                 // handle positionMode
                 ccxt::any positionMode =
                     this->safeString(params, std::string("positionMode"));
                 // if positionMode is provided, we will get it from params and
                 // send it as is
                 if (isTrue(isEqual(positionMode, ccxt::any{}))) {
                   ccxt::any hedged = false;
                   ccxt::any hedgedparamsVariable = this->handleOptionAndParams(
                       params, std::string("createOrder"),
                       std::string("hedged"), hedged);
                   hedged = ::getValue(hedgedparamsVariable, 0);
                   params = ::getValue(hedgedparamsVariable, 1);
                   ccxt::any marginMode = std::string("cross");
                   ccxt::any marginModeparamsVariable =
                       this->handleOptionAndParams(
                           params, std::string("createOrder"),
                           std::string("marginMode"), marginMode);
                   marginMode = ::getValue(marginModeparamsVariable, 0);
                   params = ::getValue(marginModeparamsVariable, 1);
                   if (isTrue(isEqual(marginMode, std::string("isolated")))) {
                     if (isTrue(hedged)) {
                       throw BadRequest(toString(
                           add(this->id,
                               std::string(" createOrder() cannot use isolated "
                                           "margin with hedged positions"))));
                     }
                     ::setValue(request, std::string("positionMode"),
                                std::string("ISOLATED"));
                   } else if (isTrue(hedged)) {
                     ::setValue(request, std::string("positionMode"),
                                std::string("HEDGE"));
                   }
                 }
                 ccxt::any isMarketOrder =
                     (isEqual(type, std::string("MARKET")));
                 ccxt::any isLimitOrder = (isEqual(type, std::string("LIMIT")));
                 ccxt::any postOnly = false;
                 // exchange-specific postOnly is the same as the unified one
                 ccxt::any postOnlyparamsVariable =
                     this->handlePostOnly(isMarketOrder, postOnly, params);
                 postOnly = ::getValue(postOnlyparamsVariable, 0);
                 params = ::getValue(postOnlyparamsVariable,
                                     1); // this will remove PO from
                                         // params.timeInForce if present
                 if (isTrue(postOnly)) {
                   ::setValue(request, std::string("postOnly"), true);
                 }
                 ccxt::any timeInForce = this->handleTimeInForce(params);
                 if (isTrue(!isEqual(timeInForce, ccxt::any{}))) {
                   ::setValue(request, std::string("timeInForce"), timeInForce);
                 }
                 ccxt::any triggerPrice =
                     this->safeString(params, std::string("triggerPrice"));
                 ccxt::any takeProfitPrice =
                     this->safeString(params, std::string("takeProfitPrice"));
                 ccxt::any stopLossPrice =
                     this->safeString(params, std::string("stopLossPrice"));
                 ccxt::any isTriggerOrder =
                     isTrue((!isEqual(triggerPrice, ccxt::any{}))) ||
                     isTrue((!isEqual(takeProfitPrice, ccxt::any{})));
                 ccxt::any isStopLossOrder =
                     (!isEqual(stopLossPrice, ccxt::any{}));
                 ccxt::any isConditionalOrder =
                     isTrue(
                         (isTrue(isTriggerOrder) || isTrue(isStopLossOrder))) &&
                     isTrue((isTrue(isMarketOrder) || isTrue(isLimitOrder)));
                 ccxt::any isAlgoOrder =
                     isTrue(isConditionalOrder) ||
                     isTrue((!isTrue(isMarketOrder) && !isTrue(isLimitOrder)));
                 if (isTrue(isTrue(isLimitOrder) ||
                            isTrue((isEqual(type, std::string("OCO")))))) {
                   if (isTrue(isEqual(price, ccxt::any{}))) {
                     throw InvalidOrder(toString(
                         add(add(add(this->id,
                                     std::string(" createOrder() requires a "
                                                 "price argument for ")),
                                 type),
                             std::string(" orders"))));
                   }
                 }
                 // here we handling with attached take profit and stop loss
                 // orders
                 ccxt::any takeProfit =
                     this->safeDict(params, std::string("takeProfit"));
                 ccxt::any stopLoss =
                     this->safeDict(params, std::string("stopLoss"));
                 if (isTrue(isTrue((!isEqual(takeProfit, ccxt::any{}))) ||
                            isTrue((!isEqual(stopLoss, ccxt::any{}))))) {
                   ccxt::any takeProfitTriggerPrice = this->safeString(
                       takeProfit, std::string("triggerPrice"));
                   ccxt::any stopLossTriggerPrice =
                       this->safeString(stopLoss, std::string("triggerPrice"));
                   if (isTrue(!isEqual(takeProfitTriggerPrice, ccxt::any{}))) {
                     ::setValue(request, std::string("takeProfitTriggerPrice"),
                                this->priceToPrecision(symbol,
                                                       takeProfitTriggerPrice));
                     ccxt::any takeProfitTriggerPriceType =
                         this->safeString(takeProfit, std::string("priceType"));
                     if (isTrue(!isEqual(takeProfitTriggerPriceType,
                                         ccxt::any{}))) {
                       ::setValue(request, std::string("takeProfitTriggerType"),
                                  this->encodeTriggerPriceType(
                                      takeProfitTriggerPriceType));
                     }
                   }
                   if (isTrue(!isEqual(stopLossTriggerPrice, ccxt::any{}))) {
                     ::setValue(
                         request, std::string("stopLossTriggerPrice"),
                         this->priceToPrecision(symbol, stopLossTriggerPrice));
                     ccxt::any stopLossTriggerPriceType =
                         this->safeString(stopLoss, std::string("priceType"));
                     if (isTrue(
                             !isEqual(stopLossTriggerPriceType, ccxt::any{}))) {
                       ::setValue(request, std::string("stopLossTriggerType"),
                                  this->encodeTriggerPriceType(
                                      stopLossTriggerPriceType));
                     }
                   }
                   params =
                       this->omit(params, ccxt::list{std::string("takeProfit"),
                                                     std::string("stopLoss")});
                 }
                 ccxt::any response = ccxt::any{};
                 if (!isTrue(isAlgoOrder)) {
                   ::setValue(request, std::string("orderType"), type);
                   if (isTrue(isLimitOrder)) {
                     ::setValue(request, std::string("orderPrice"),
                                this->priceToPrecision(symbol, price));
                   }
                   //
                   //     {
                   //         "status": 2,
                   //         "type": 0,
                   //         "symbol": "BTC-PERP",
                   //         "postOnly": false,
                   //         "orderSide": "BUY",
                   //         "orderId": "0251ea47-88b5-48c0-aeb3-b38774fd1f90",
                   //         "clOrderID": "",
                   //         "timestamp": 1784882344361,
                   //         "price": 57009.5,
                   //         "avgFilledPrice": 0,
                   //         "message": null,
                   //         "originalOrderSize": 1,
                   //         "currentOrderSize": 1,
                   //         "filledSize": 0,
                   //         "totalFilledSize": 0,
                   //         "remainingSize": 1,
                   //         "positionMode": "ONE_WAY",
                   //         "positionDirection": null,
                   //         "positionId": "BTC-PERP-USDT",
                   //         "timeInForce": "GTC"
                   //     }
                   //
                   response =
                       awaitValue(this->privatePostFuturesApiV3TradeOrders(
                           this->extend(request, params)));
                 } else {
                   if (isTrue(isConditionalOrder)) {
                     // the futures conditional variant has no trigger direction
                     // field, it takes a plain trigger price with an optional
                     // limit price
                     ::setValue(request, std::string("orderType"),
                                std::string("CONDITIONAL"));
                     ccxt::any triggerPriceToSend = triggerPrice;
                     if (isTrue(isEqual(triggerPriceToSend, ccxt::any{}))) {
                       triggerPriceToSend = takeProfitPrice;
                     }
                     if (isTrue(isEqual(triggerPriceToSend, ccxt::any{}))) {
                       triggerPriceToSend = stopLossPrice;
                     }
                     ::setValue(
                         request, std::string("triggerPrice"),
                         this->priceToPrecision(symbol, triggerPriceToSend));
                     ccxt::any triggerPriceType = this->safeString(
                         params, std::string("triggerPriceType"),
                         std::string("mark"));
                     ::setValue(request, std::string("triggerType"),
                                this->encodeTriggerPriceType(triggerPriceType));
                     if (isTrue(isLimitOrder)) {
                       ::setValue(request, std::string("orderPrice"),
                                  this->priceToPrecision(symbol, price));
                     }
                     params = this->omit(
                         params, ccxt::list{std::string("triggerPrice"),
                                            std::string("takeProfitPrice"),
                                            std::string("stopLossPrice"),
                                            std::string("triggerPriceType")});
                   } else {
                     ::setValue(request, std::string("orderType"), type);
                     if (isTrue(isEqual(type, std::string("OCO")))) {
                       // the price argument is the limit price of the take
                       // profit leg, the stopPrice param is the limit price of
                       // the stop loss leg and the triggerPrice param is where
                       // the stop loss leg fires
                       ::setValue(request, std::string("takeProfitOrderPrice"),
                                  this->priceToPrecision(symbol, price));
                       ccxt::any stopPrice =
                           this->safeString(params, std::string("stopPrice"));
                       if (isTrue(!isEqual(stopPrice, ccxt::any{}))) {
                         ::setValue(request, std::string("stopLossOrderPrice"),
                                    this->priceToPrecision(symbol, stopPrice));
                       }
                       if (isTrue(!isEqual(triggerPrice, ccxt::any{}))) {
                         ::setValue(
                             request, std::string("stopLossTriggerPrice"),
                             this->priceToPrecision(symbol, triggerPrice));
                       }
                       ccxt::any triggerPriceType = this->safeString(
                           params, std::string("triggerPriceType"),
                           std::string("mark"));
                       ::setValue(
                           request, std::string("stopLossTriggerType"),
                           this->encodeTriggerPriceType(triggerPriceType));
                       params = this->omit(
                           params, ccxt::list{std::string("stopPrice"),
                                              std::string("triggerPrice"),
                                              std::string("triggerPriceType")});
                     } else if (isTrue(isEqual(type, std::string("PEG")))) {
                       // the required deviation and stealth params pass
                       // through, the optional price argument becomes a
                       // worst-price bound
                       if (isTrue(!isEqual(price, ccxt::any{}))) {
                         ::setValue(request, std::string("orderPrice"),
                                    this->priceToPrecision(symbol, price));
                       }
                     } else if (isTrue(
                                    isEqual(type, std::string("TRAILING")))) {
                       ccxt::any trailingAmount = this->safeString(
                           params, std::string("trailingAmount"));
                       ccxt::any trailingPercent = this->safeString(
                           params, std::string("trailingPercent"));
                       if (isTrue(!isEqual(trailingAmount, ccxt::any{}))) {
                         ::setValue(
                             request, std::string("trailValue"),
                             this->priceToPrecision(symbol, trailingAmount));
                         ::setValue(request, std::string("trailValueType"),
                                    std::string("DISTANCE"));
                       } else if (isTrue(
                                      !isEqual(trailingPercent, ccxt::any{}))) {
                         ::setValue(request, std::string("trailValue"),
                                    trailingPercent);
                         ::setValue(request, std::string("trailValueType"),
                                    std::string("PERCENTAGE"));
                       }
                       ccxt::any triggerPriceType = this->safeString(
                           params, std::string("triggerPriceType"),
                           std::string("mark"));
                       ::setValue(
                           request, std::string("trailTriggerPriceType"),
                           this->encodeTriggerPriceType(triggerPriceType));
                       params = this->omit(
                           params, ccxt::list{std::string("trailingAmount"),
                                              std::string("trailingPercent"),
                                              std::string("triggerPriceType")});
                     }
                   }
                   response =
                       awaitValue(this->privatePostFuturesApiV3TradeOrdersAlgo(
                           this->extend(request, params)));
                 }
                 // the normal futures endpoint responds with a single order
                 // dict, keep a one element array guard in case a gateway wraps
                 // it
                 ccxt::any order = response;
                 if (isTrue(isArray(response))) {
                   order = this->safeDict(response, 0, ccxt::dict{});
                 }
                 return this->parseOrder(order, market);
               })
        .share();
  }

  virtual ccxt::any encodeTriggerPriceType(ccxt::any priceType) {
    ccxt::any priceTypes = ccxt::dict{
        {std::string("last"), std::string("LAST_PRICE")},
        {std::string("mark"), std::string("MARK_PRICE")},
        {std::string("index"), std::string("INDEX_PRICE")},
        {std::string("lastPrice"), std::string("LAST_PRICE")},
        {std::string("markPrice"), std::string("MARK_PRICE")},
        {std::string("indexPrice"), std::string("INDEX_PRICE")},
    };
    return this->safeString(priceTypes, priceType, priceType);
  }

  /**
   * @method
   * @name btse#fetchOpenOrder
   * @description fetches information on an open order made by the user
   * @see https://docs.btse.com/spot/rest/get-order
   * @see https://docs.btse.com/futures/rest/get-orders
   * @param {string} id the order id
   * @param {string} [symbol] unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.clientOrderId] a unique id for the order
   * @param {string} [params.type] 'spot', 'swap' or 'future', default is 'spot'
   * @param {bool} [params.includeCancelled] *contract markets only* if true,
   * cancelled orders are included in the lookup
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<ccxt::any>
  fetchOpenOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any request = ccxt::dict{};
                 ccxt::any clientOrderId =
                     this->safeString(params, std::string("clientOrderId"));
                 if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
                   ::setValue(request, std::string("clOrderId"), clientOrderId);
                   params = this->omit(params, std::string("clientOrderId"));
                 } else if (isTrue(isEqual(id, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(" fetchOpenOrder() requires an id argument "
                                   "or a clientOrderId parameter"))));
                 } else {
                   ::setValue(request, std::string("orderId"), id);
                 }
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any marketType = std::string("spot");
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchOrder"), market, params, marketType);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   response = awaitValue(this->privateGetSpotApiV4TradeOrder(
                       this->extend(request, params)));
                 } else {
                   // the futures endpoint doubles as the single order lookup
                   // when an order id is sent and responds with a bare array
                   response =
                       awaitValue(this->privateGetFuturesApiV3TradeOrders(
                           this->extend(request, params)));
                 }
                 // accept a bare order dict, a data envelope and a one element
                 // array
                 ccxt::any order =
                     this->safeValue(response, std::string("data"), response);
                 if (isTrue(isArray(order))) {
                   order = this->safeDict(order, 0, ccxt::dict{});
                 }
                 return this->parseOrder(order, market);
               })
        .share();
  }

  /**
   * @method
   * @name btse#editOrder
   * @description edit a trade order
   * @see https://docs.btse.com/spot/rest/amend-order
   * @see https://docs.btse.com/futures/rest/amend-order
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit' (not used by btse)
   * @param {string} side 'buy' or 'sell' (not used by btse)
   * @param {float} [amount] how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.clientOrderId] a unique id for the order, required
   * if id is not provided
   * @param {float} [params.triggerPrice] the price that a trigger order is
   * triggered at
   * @param {bool} [params.totalAmountMode] if true, the amount is treated as
   * the new total order quantity including the already filled portion, default
   * is false
   * @param {bool} [params.slide] *contract markets only* if true and only the
   * price is amended, the price slides to the best available price
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  editOrder(ccxt::any id, ccxt::any symbol, ccxt::any type, ccxt::any side,
            ccxt::any amount = ccxt::any{}, ccxt::any price = ccxt::any{},
            ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{};
                 ccxt::any clientOrderId =
                     this->safeString(params, std::string("clientOrderId"));
                 if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
                   ::setValue(request, std::string("clOrderId"), clientOrderId);
                   params = this->omit(params, std::string("clientOrderId"));
                 } else if (isTrue(isEqual(id, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(" editOrder() requires an id argument "
                                       "or a clientOrderId parameter"))));
                 } else {
                   ::setValue(request, std::string("orderId"), id);
                 }
                 ccxt::any triggerPrice =
                     this->safeString(params, std::string("triggerPrice"));
                 if (isTrue(!isEqual(triggerPrice, ccxt::any{}))) {
                   ::setValue(request, std::string("triggerPrice"),
                              this->priceToPrecision(symbol, triggerPrice));
                   params = this->omit(params, std::string("triggerPrice"));
                 }
                 if (isTrue(!isEqual(amount, ccxt::any{}))) {
                   ::setValue(request, std::string("orderSize"),
                              this->amountToPrecision(symbol, amount));
                 }
                 if (isTrue(!isEqual(price, ccxt::any{}))) {
                   ::setValue(request, std::string("orderPrice"),
                              this->priceToPrecision(symbol, price));
                 }
                 ccxt::any isSlide =
                     this->safeBool(params, std::string("slide"), false);
                 if (isTrue(
                         isTrue(isTrue(isTrue((isEqual(amount, ccxt::any{}))) &&
                                       isTrue((isEqual(price, ccxt::any{})))) &&
                                isTrue((isEqual(triggerPrice, ccxt::any{})))) &&
                         isTrue((!isEqual(isSlide, true))))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " editOrder() requires an amount argument, a "
                               "price argument or a triggerPrice parameter"))));
                 }
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                    true))) {
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                   response = awaitValue(this->privatePutSpotApiV4TradeOrders(
                       this->extend(request, params)));
                 } else {
                   // the futures amend requires an explicit amendType
                   // discriminator which can change the price and size together
                   // or a single field
                   ::setValue(request, std::string("symbol"),
                              this->futuresRequestId(market));
                   if (isTrue(!isEqual(triggerPrice, ccxt::any{}))) {
                     if (isTrue(isTrue((!isEqual(amount, ccxt::any{}))) ||
                                isTrue((!isEqual(price, ccxt::any{}))))) {
                       throw BadRequest(toString(add(
                           this->id,
                           std::string(" editOrder() can not amend the trigger "
                                       "price together with the price or the "
                                       "amount on contract markets"))));
                     }
                     ::setValue(request, std::string("amendType"),
                                std::string("TRIGGER_PRICE"));
                   } else if (isTrue(isTrue((!isEqual(amount, ccxt::any{}))) &&
                                     isTrue((!isEqual(price, ccxt::any{}))))) {
                     ::setValue(request, std::string("amendType"),
                                std::string("ALL"));
                   } else if (isTrue(!isEqual(amount, ccxt::any{}))) {
                     ::setValue(request, std::string("amendType"),
                                std::string("SIZE"));
                   } else {
                     ::setValue(request, std::string("amendType"),
                                std::string("PRICE"));
                   }
                   response =
                       awaitValue(this->privatePutFuturesApiV3TradeOrders(
                           this->extend(request, params)));
                 }
                 ccxt::any order = this->safeDict(response, 0, ccxt::dict{});
                 return this->parseOrder(order, market);
               })
        .share();
  }

  /**
   * @method
   * @name btse#cancelOrder
   * @see https://docs.btse.com/spot/rest/cancel-order
   * @see https://docs.btse.com/futures/rest/cancel-order
   * @description cancels an open order
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.clientOrderId] a unique id for the order, required
   * if id is not provided
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " cancelOrder() requires a symbol argument"))));
                 }
                 awaitValue(this->loadMarkets());
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{};
                 ccxt::any clientOrderId =
                     this->safeString(params, std::string("clientOrderId"));
                 if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
                   ::setValue(request, std::string("clOrderId"), clientOrderId);
                   params = this->omit(params, std::string("clientOrderId"));
                 } else if (isTrue(isEqual(id, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(" cancelOrder() requires an id argument "
                                       "or a clientOrderId parameter"))));
                 } else {
                   ::setValue(request, std::string("orderId"), id);
                 }
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                    true))) {
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                   response =
                       awaitValue(this->privateDeleteSpotApiV4TradeOrders(
                           this->extend(request, params)));
                 } else {
                   //
                   //     [
                   //         {
                   //             "orderId":
                   //             "0251ea47-88b5-48c0-aeb3-b38774fd1f90",
                   //             "clOrderId": "",
                   //             "symbol": "BTC-PERP",
                   //             "orderSide": "BUY",
                   //             "type": 76,
                   //             "orderPrice": 56439.4,
                   //             "orderSize": 1,
                   //             "filledSize": 0,
                   //             "status": 6,
                   //             "timestamp": 1784882344500
                   //         }
                   //     ]
                   //
                   ::setValue(request, std::string("symbol"),
                              this->futuresRequestId(market));
                   response =
                       awaitValue(this->privateDeleteFuturesApiV3TradeOrders(
                           this->extend(request, params)));
                 }
                 ccxt::any order = this->safeDict(response, 0, ccxt::dict{});
                 return this->parseOrder(order, market);
               })
        .share();
  }

  /**
   * @method
   * @name btse#cancelAllOrders
   * @description cancel all open orders in a market
   * @see https://docs.btse.com/spot/rest/cancel-all-orders
   * @see https://btsecom.github.io/docs/futuresV2_3/en/#cancel-order
   * @param {string} [symbol] unified market symbol of the market to cancel
   * orders in, on spot markets omit it to cancel every open order across all
   * pairs
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.type] 'spot', 'swap' or 'future', default is
   * 'spot', used when the symbol is omitted
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelAllOrders(ccxt::any symbol = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any marketType = std::string("spot");
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("cancelAllOrders"), market, params,
                         marketType);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 ccxt::any request = ccxt::dict{};
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   // the literal ALL value cancels every open order across all
                   // pairs
                   ::setValue(
                       request, std::string("symbol"),
                       (isTrue((!isEqual(market, ccxt::any{})))
                            ? ccxt::any(::getValue(market, std::string("id")))
                            : ccxt::any(std::string("ALL"))));
                   response =
                       awaitValue(this->privateDeleteSpotApiV4TradeOrdersAll(
                           this->extend(request, params)));
                 } else {
                   if (isTrue(isEqual(market, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(
                         add(this->id,
                             std::string(" cancelAllOrders() requires a symbol "
                                         "argument for contract markets"))));
                   }
                   // the unified futures api has no cancel all endpoint, the
                   // legacy endpoint cancels every order for the symbol when no
                   // order id is sent, and it identifies contracts by the short
                   // symbol form
                   ::setValue(request, std::string("symbol"),
                              this->futuresRequestId(market));
                   response = awaitValue(this->privateDeleteFuturesApiV23Order(
                       this->extend(request, params)));
                 }
                 return this->parseOrders(response, market);
               })
        .share();
  }

  /**
   * @method
   * @name btse#cancelAllOrdersAfter
   * @description dead man's switch, cancel all orders after the given timeout
   * @see https://docs.btse.com/spot/rest/cancel-all-after
   * @see https://docs.btse.com/futures/rest/cancel-all-after
   * @param {number} timeout time in milliseconds, 0 represents cancel the timer
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.type] 'spot', 'swap' or 'future', default is 'spot'
   * @returns {object} the api result
   */
  std::shared_future<ccxt::any>
  cancelAllOrdersAfter(ccxt::any timeout,
                       ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any request = ccxt::dict{};
                 ccxt::any response = ccxt::any{};
                 ccxt::any marketType = std::string("spot");
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("cancelAllOrdersAfter"), ccxt::any{},
                         params, marketType);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   ::setValue(request, std::string("timeout"), timeout);
                   response = awaitValue(
                       this->privatePostSpotApiV4TradeOrdersCancelAllAfter(
                           this->extend(request, params)));
                 } else {
                   // the futures param is named timeoutMs and is required, zero
                   // disarms
                   ::setValue(request, std::string("timeoutMs"), timeout);
                   response = awaitValue(
                       this->privatePostFuturesApiV3TradeOrdersCancelAllAfter(
                           this->extend(request, params)));
                 }
                 return response;
               })
        .share();
  }

  /**
   * @method
   * @name btse#fetchOpenOrders
   * @description fetch all unfilled currently open orders
   * @see https://docs.btse.com/spot/rest/get-orders
   * @see https://docs.btse.com/futures/rest/get-orders
   * @param {string} [symbol] unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for,
   * filtered client-side
   * @param {int} [limit] the maximum number of open orders structures to
   * retrieve, filtered client-side
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.type] 'spot', 'swap' or 'future', default is 'spot'
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOpenOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                  ccxt::any limit = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any marketType = std::string("spot");
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchOpenOrders"), market, params,
                         marketType);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   if (isTrue(!isEqual(market, ccxt::any{}))) {
                     ::setValue(request, std::string("symbol"),
                                ::getValue(market, std::string("id")));
                   }
                   response = awaitValue(this->privateGetSpotApiV4TradeOrders(
                       this->extend(request, params)));
                 } else {
                   if (isTrue(!isEqual(market, ccxt::any{}))) {
                     ::setValue(request, std::string("symbol"),
                                this->futuresRequestId(market));
                   }
                   response =
                       awaitValue(this->privateGetFuturesApiV3TradeOrders(
                           this->extend(request, params)));
                 }
                 // the endpoints have no server side time filters, accept a
                 // bare array and a data envelope and filter client-side
                 ccxt::any rows =
                     this->safeList(response, std::string("data"), response);
                 return this->parseOrders(rows, market, since, limit);
               })
        .share();
  }

  ccxt::any parseOrder(ccxt::any order,
                       ccxt::any market = ccxt::any{}) override {
    //
    // createOrder - spot
    //     {
    //         "status": 2,
    //         "symbol": "ETH-USDT",
    //         "orderType": 76,
    //         "price": 1000,
    //         "side": "BUY",
    //         "orderID": "cde4fb37-2e2b-437e-a816-4b55b2e2b7c7",
    //         "timestamp": 1770813053751,
    //         "triggerPrice": 0,
    //         "stopPrice": null,
    //         "trigger": false,
    //         "message": "",
    //         "clOrderID": null,
    //         "stealth": 1,
    //         "deviation": 1,
    //         "postOnly": false,
    //         "orderDetailType": null,
    //         "originalOrderBaseSize": 0.0001,
    //         "originalOrderQuoteSize": null,
    //         "currentOrderBaseSize": 0.0001,
    //         "currentOrderQuoteSize": null,
    //         "remainingOrderBaseSize": 0.0001,
    //         "remainingOrderQuoteSize": null,
    //         "filledBaseSize": 0,
    //         "totalFilledBaseSize": 0,
    //         "orderCurrency": "base",
    //         "avgFilledPrice": 0,
    //         "time_in_force": "GTC"
    //     }
    //
    // createOrder - swap
    //     {
    //         "status": 4,
    //         "symbol": "ETH-PERP",
    //         "orderType": 77,
    //         "price": 1956.59,
    //         "side": "BUY",
    //         "orderID": "5c6a26db-8cfb-45c7-b25d-56927bc36795",
    //         "timestamp": 1770821231984,
    //         "triggerPrice": 0,
    //         "trigger": false,
    //         "deviation": 100,
    //         "stealth": 100,
    //         "message": "",
    //         "avgFilledPrice": 1956.59,
    //         "clOrderID": "",
    //         "originalOrderSize": 1,
    //         "currentOrderSize": 1,
    //         "filledSize": 1,
    //         "totalFilledSize": 1,
    //         "remainingSize": 0,
    //         "postOnly": false,
    //         "orderDetailType": null,
    //         "positionMode": "ONE_WAY",
    //         "positionDirection": null,
    //         "positionId": "ETH-PERP-USDT",
    //         "time_in_force": "GTC"
    //     }
    //
    ccxt::any marketId =
        this->safeString2(order, std::string("symbol"), std::string("market"));
    market = this->safeMarket(marketId, market);
    ccxt::any timestamp = this->safeInteger(order, std::string("timestamp"));
    // open_orders rows carry no numeric status - the state lives in
    // orderState (STATUS_ACTIVE / STATUS_INACTIVE), and time_in_force
    // is spelled timeInForce there (observed live), so both fall back
    ccxt::any rawStatus = this->safeString2(order, std::string("status"),
                                            std::string("orderState"));
    ccxt::any rawType =
        this->safeString2(order, std::string("orderType"), std::string("type"));
    ccxt::any status = this->parseOrderStatus(rawStatus);
    ccxt::any orderType = this->parseOrderType(rawType);
    if (isTrue(isTrue((isEqual(orderType, std::string("market")))) &&
               isTrue((isEqual(status, std::string("open")))))) {
      // market orders never rest on the book, the exchange reports the
      // partially filled code on them when a residual quote dust amount
      // cannot fill, observed live, such orders are finished
      status = std::string("closed");
    }
    ccxt::any rawTimeInForce = this->safeString2(
        order, std::string("time_in_force"), std::string("timeInForce"));
    return this->safeOrder(
        ccxt::dict{
            {std::string("info"), order},
            {std::string("id"), this->safeString2(order, std::string("orderID"),
                                                  std::string("orderId"))},
            {std::string("clientOrderId"),
             this->safeString2(order, std::string("clOrderID"),
                               std::string("clOrderId"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("lastTradeTimestamp"), ccxt::any{}},
            {std::string("lastUpdateTimestamp"), ccxt::any{}},
            {std::string("status"), status},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("type"), orderType},
            {std::string("timeInForce"),
             this->parseTimeInForce(rawTimeInForce)},
            {std::string("postOnly"),
             this->safeBool(order, std::string("postOnly"))},
            {std::string("reduceOnly"),
             this->safeBool(order, std::string("reduceOnly"))},
            {std::string("side"),
             this->safeStringLower2(order, std::string("side"),
                                    std::string("orderSide"))},
            {std::string("price"),
             this->safeString2(order, std::string("price"),
                               std::string("orderPrice"))},
            {std::string("triggerPrice"),
             this->omitZero(
                 this->safeString2(order, std::string("triggerOriginalPrice"),
                                   std::string("triggerPrice")))},
            {std::string("stopLossPrice"), ccxt::any{}},
            {std::string("takeProfitPrice"), ccxt::any{}},
            {std::string("amount"),
             this->safeStringN(order,
                               ccxt::list{std::string("currentOrderBaseSize"),
                                          std::string("currentOrderSize"),
                                          std::string("orderSize")})},
            {std::string("filled"),
             this->safeStringN(order,
                               ccxt::list{std::string("totalFilledBaseSize"),
                                          std::string("totalFilledSize"),
                                          std::string("filledSize")})},
            {std::string("remaining"),
             this->safeString2(order, std::string("remainingOrderBaseSize"),
                               std::string("remainingSize"))},
            {std::string("cost"), ccxt::any{}},
            {std::string("trades"), ccxt::any{}},
            {std::string("fee"), ccxt::any{}},
            {std::string("average"), this->omitZero(this->safeString2(
                                         order, std::string("avgFilledPrice"),
                                         std::string("averageFillPrice")))},
        },
        market);
  }

  virtual ccxt::any parseOrderStatus(ccxt::any status) {
    ccxt::any statuses = ccxt::dict{
        {std::string("2"), std::string("open")},
        {std::string("3"), std::string("closed")},
        {std::string("4"), std::string("closed")},
        {std::string("5"), std::string("open")},
        {std::string("6"), std::string("canceled")},
        {std::string("7"), std::string("refunded")},
        {std::string("8"), std::string("rejected")},
        {std::string("9"), std::string("open")},
        {std::string("10"), std::string("open")},
        {std::string("15"), std::string("rejected")},
        {std::string("16"), std::string("rejected")},
        {std::string("17"), std::string("rejected")},
        {std::string("123"), std::string("open")},
        {std::string("STATUS_ACTIVE"), std::string("open")},
        {std::string("STATUS_INACTIVE"), std::string("canceled")},
        {std::string("ORDER_INSERTED"), std::string("open")},
        {std::string("ORDER_PARTIALLY_TRANSACTED"), std::string("open")},
        {std::string("ORDER_FULLY_TRANSACTED"), std::string("closed")},
        {std::string("ORDER_CANCELLED"), std::string("canceled")},
    };
    return this->safeString(statuses, status, status);
  }

  virtual ccxt::any parseOrderType(ccxt::any type) {
    ccxt::any types = ccxt::dict{
        {std::string("76"), std::string("limit")},
        {std::string("77"), std::string("market")},
        {std::string("80"), std::string("limit")},
    };
    return this->safeString(types, type, type);
  }

  virtual ccxt::any parseTimeInForce(ccxt::any timeInForce) {
    ccxt::any values = ccxt::dict{
        {std::string("GTC"), std::string("GTC")},
        {std::string("IOC"), std::string("IOC")},
        {std::string("FOK"), std::string("FOK")},
        {std::string("HALFSEC"), std::string("GTD")},
        {std::string("HALFMIN"), std::string("GTD")},
        {std::string("FIVEMIN"), std::string("GTD")},
        {std::string("HOUR"), std::string("GTD")},
        {std::string("TWELVEHOUR"), std::string("GTD")},
        {std::string("DAY"), std::string("GTD")},
        {std::string("WEEK"), std::string("GTD")},
        {std::string("MONTH"), std::string("GTD")},
    };
    return this->safeString(values, timeInForce, timeInForce);
  }

  /**
   * @method
   * @name btse#fetchTradingFees
   * @description fetch the trading fees for multiple markets
   * @see https://docs.btse.com/spot/rest/get-fees
   * @see https://btsecom.github.io/docs/futuresV2_3/en/#query-account-fee
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.type] 'spot', 'swap' or 'future' (default is
   * 'spot')
   * @returns {object} a dictionary of [fee structures]{@link
   * https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
   */
  std::shared_future<ccxt::any>
  fetchTradingFees(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any response = ccxt::any{};
                 ccxt::any marketType = std::string("spot");
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchTradingFees"), ccxt::any{}, params,
                         marketType);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   response =
                       awaitValue(this->privateGetSpotApiV4TradeFees(params));
                 } else {
                   // the futures fees stay on the legacy endpoint, the unified
                   // futures api has no fees route
                   response = awaitValue(
                       this->privateGetFuturesApiV23UserFees(params));
                 }
                 //
                 //     [
                 //         {
                 //             "symbol": "FUSD-USD",
                 //             "makerFee": 0.002,
                 //             "takerFee": 0.002
                 //         }
                 //     ]
                 //
                 ccxt::any rows =
                     this->safeList(response, std::string("data"), response);
                 ccxt::any responseList = this->arrayConcat(ccxt::list{}, rows);
                 ccxt::any result = ccxt::dict{};
                 for (ccxt::any i = 0;
                      isLessThan(i, getArrayLength(responseList));
                      postFixIncrement(i)) {
                   ccxt::any feeInfo = ::getValue(responseList, i);
                   ccxt::any marketId =
                       this->safeString(feeInfo, std::string("symbol"));
                   ccxt::any market = this->safeMarket(marketId);
                   ccxt::any symbol = ::getValue(market, std::string("symbol"));
                   ccxt::any makerFee =
                       this->safeNumber(feeInfo, std::string("makerFee"));
                   ccxt::any takerFee =
                       this->safeNumber(feeInfo, std::string("takerFee"));
                   ::setValue(result, symbol,
                              ccxt::dict{
                                  {std::string("info"), feeInfo},
                                  {std::string("symbol"), symbol},
                                  {std::string("maker"), makerFee},
                                  {std::string("taker"), takerFee},
                                  {std::string("percentage"), true},
                                  {std::string("tierBased"), true},
                              });
                 }
                 return result;
               })
        .share();
  }

  virtual std::shared_future<ccxt::any> requestWalletHistoryRows(
      ccxt::any methodName, ccxt::any historyTypes,
      ccxt::any code = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 // the helper always receives a non empty history type list,
                 // the list is rebuilt through safeList so the transpilers
                 // treat it as an array in every runtime
                 ccxt::any typesList = this->safeList(
                     ccxt::dict{
                         {std::string("types"), historyTypes},
                     },
                     std::string("types"), ccxt::list{});
                 awaitValue(this->loadMarkets());
                 ccxt::any walletType = this->safeString(
                     params, std::string("walletType"), std::string("SPOT"));
                 ccxt::any request = ccxt::dict{
                     {std::string("walletType"), walletType},
                 };
                 // the endpoint applies a server side history type filter sent
                 // as a json encoded array in the query string, verified live
                 ::setValue(request, std::string("historyTypes"),
                            this->json(typesList));
                 params = this->omit(params, std::string("walletType"));
                 ccxt::any currency = ccxt::any{};
                 if (isTrue(!isEqual(code, ccxt::any{}))) {
                   currency = this->currency(code);
                   ::setValue(request, std::string("asset"),
                              ::getValue(currency, std::string("id")));
                 } else if (isTrue(isEqual(walletType, std::string("SPOT")))) {
                   throw ArgumentsRequired(toString(
                       add(add(add(this->id, std::string(" ")), methodName),
                           std::string("() requires a code argument for the "
                                       "spot wallet history"))));
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("pageSize"), limit);
                 }
                 ccxt::any until = ccxt::any{};
                 ccxt::any untilparamsVariable = this->handleOptionAndParams(
                     params, methodName, std::string("until"));
                 until = ::getValue(untilparamsVariable, 0);
                 params = ::getValue(untilparamsVariable, 1);
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   ::setValue(request, std::string("endTime"), until);
                 }
                 ccxt::any response = awaitValue(
                     this->privateGetPublicApiWalletV1UserWalletHistory(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "code": 1,
                 //         "msg": "Success",
                 //         "time": 1786624541092,
                 //         "data": [
                 //             {
                 //                 "transactionTime": 1786510157962,
                 //                 "type": "DEPOSIT",
                 //                 "walletName": "SPOT@",
                 //                 "asset": "USDT",
                 //                 "netAmount": "100",
                 //                 "amount": "100",
                 //                 "transactionRef": "2026081200000367",
                 //                 "status": "COMPLETED",
                 //                 "description": null,
                 //                 "fees": "0",
                 //                 "cryptoNetwork": "ERC20",
                 //                 "toAddress":
                 //                 "0x36bd7cbc486658c9777672fe742971bda65d5e6f",
                 //                 "confirmTimes": "(15/15)",
                 //                 "txId":
                 //                 "0xb4d88986d013f799d78e6232792c44b45dff1213a015171ddcf4adfcd283b3fd"
                 //             }
                 //         ],
                 //         "success": true
                 //     }
                 //
                 ccxt::any rawRows =
                     this->safeList(response, std::string("data"), response);
                 // the requested types are also filtered client side over both
                 // the legacy and the unified enum vocabularies as the legacy
                 // endpoint ignored the filter and returned the whole mixed
                 // ledger
                 ccxt::any allowed = ccxt::dict{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(typesList));
                      postFixIncrement(i)) {
                   ccxt::any historyType = ::getValue(typesList, i);
                   ::setValue(allowed, historyType, true);
                   ::setValue(allowed,
                              this->capitalize(toLowerCase(historyType)), true);
                 }
                 ccxt::any rows = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(rawRows));
                      postFixIncrement(i)) {
                   ccxt::any entry = ::getValue(rawRows, i);
                   ccxt::any type = this->safeString(entry, std::string("type"),
                                                     std::string(""));
                   if (isTrue(inOp(allowed, type))) {
                     arrayPush(rows, entry);
                   }
                 }
                 return ccxt::list{rows, currency};
               })
        .share();
  }

  /**
   * @method
   * @name btse#fetchDepositsWithdrawals
   * @description fetch history of deposits and withdrawals
   * @see https://docs.btse.com/wallet/rest/get-user-wallet-history
   * @param {string} [code] unified currency code, required for the default spot
   * wallet
   * @param {int} [since] the earliest time in ms to fetch transactions for
   * @param {int} [limit] the maximum number of transaction structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch transactions
   * for, excluded
   * @param {string} [params.walletType] wallet to query, SPOT by default,
   * ISOLATED requires params.walletName
   * @returns {object[]} a list of [transaction structures]{@link
   * https://docs.ccxt.com/#/?id=transaction-structure}
   */
  std::shared_future<ccxt::any> fetchDepositsWithdrawals(
      ccxt::any code = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any rowscurrencyVariable =
                     awaitValue(this->requestWalletHistoryRows(
                         std::string("fetchDepositsWithdrawals"),
                         ccxt::list{std::string("DEPOSIT"),
                                    std::string("WITHDRAW")},
                         code, since, limit, params));
                 ccxt::any rows = ::getValue(rowscurrencyVariable, 0);
                 ccxt::any currency = ::getValue(rowscurrencyVariable, 1);
                 return this->parseTransactions(rows, currency, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name btse#fetchDeposits
   * @description fetch all deposits made to an account
   * @see https://docs.btse.com/wallet/rest/get-user-wallet-history
   * @param {string} [code] unified currency code, required for the default spot
   * wallet
   * @param {int} [since] the earliest time in ms to fetch deposits for
   * @param {int} [limit] the maximum number of transaction structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch deposits for,
   * excluded
   * @param {string} [params.walletType] wallet to query, SPOT by default,
   * ISOLATED requires params.walletName
   * @returns {object[]} a list of [transaction structures]{@link
   * https://docs.ccxt.com/#/?id=transaction-structure}
   */
  std::shared_future<ccxt::any>
  fetchDeposits(ccxt::any code = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any rowscurrencyVariable =
                     awaitValue(this->requestWalletHistoryRows(
                         std::string("fetchDeposits"),
                         ccxt::list{std::string("DEPOSIT")}, code, since, limit,
                         params));
                 ccxt::any rows = ::getValue(rowscurrencyVariable, 0);
                 ccxt::any currency = ::getValue(rowscurrencyVariable, 1);
                 return this->parseTransactions(rows, currency, since, limit);
               })
        .share();
  }

